import heapq

def kth_smallest(arr, k):
    heapq.heapify(arr)
    for _ in range(k - 1):
        heapq.heappop(arr)
    return arr[0]

def kth_largest(arr, k):
    return -heapq.nsmallest(k, arr)[-1]

