int minDiff(vector<int>& arr, int k) {
    int n = arr.size();
    sort(arr.begin(), arr.end());
    int ans = arr[n - 1] - arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] < k) continue;
        int tempMin = min(arr[0] + k, arr[i] - k);
        int tempMax = max(arr[i - 1] + k, arr[n - 1] - k);
        ans = min(ans, tempMax - tempMin);
    }
    return ans;
}

