def merge(arr1, arr2):
    m, n = len(arr1), len(arr2)
    gap = math.ceil((m + n) / 2)
    while gap > 0:
        i = 0
        while i + gap < m + n:
            j = i + gap
            if j < m:
                if arr1[i] > arr1[j]:
                    arr1[i], arr1[j] = arr1[j], arr1[i]
            elif i < m and j >= m:
                if arr1[i] > arr2[j - m]:
                    arr1[i], arr2[j - m] = arr2[j - m], arr1[i]
            else:
                if arr2[i - m] > arr2[j - m]:
                    arr2[i - m], arr2[j - m] = arr2[j - m], arr2[i - m]
            i += 1
        if gap == 1:
            break
        gap = math.ceil(gap / 2)

solution.cpp:
void merge(vector<int>& a, vector<int>& b) {
    int m = a.size(), n = b.size();
    int gap = ceil((m + n) / 2.0);
    while (gap > 0) {
        int i = 0;
        while (i + gap < m + n) {
            int j = i + gap;
            if (j < m) {
                if (a[i] > a[j]) swap(a[i], a[j]);
            } else if (i < m && j >= m) {
                if (a[i] > b[j - m]) swap(a[i], b[j - m]);
            } else {
                if (b[i - m] > b[j - m]) swap(b[i - m], b[j - m]);
            }
            i++;
        }
        if (gap == 1) break;
        gap = ceil(gap / 2.0);
    }
}

