    int gap = (int) Math.ceil((m + n) / 2.0);
    while (gap > 0) {
        int i = 0;
        while (i + gap < m + n) {
            int j = i + gap;
            if (j < m) {
                if (a[i] > a[j]) { int t = a[i]; a[i] = a[j]; a[j] = t; }
            } else if (i < m && j >= m) {
                if (a[i] > b[j - m]) { int t = a[i]; a[i] = b[j - m]; b[j - m] = t; }
            } else {
                if (b[i - m] > b[j - m]) { int t = b[i - m]; b[i - m] = b[j - m]; b[j - m] = t; }
            }
            i++;
        }
        if (gap == 1) break;
        gap = (int) Math.ceil(gap / 2.0);
    }
}

