def count_pairs(arr, target):
    from collections import Counter
    freq = Counter(arr)
    count = 0
    seen = set()
    for num in arr:
        complement = target - num
        if complement in freq:
            if complement == num:
                count += freq[num] * (freq[num] - 1) // 2
            elif complement not in seen:
                count += freq[num] * freq[complement]
        seen.add(num)
    return count

