int countPairs(vector<int>& arr, int target) {
    unordered_map<int, int> freq;
    for (int x : arr) freq[x]++;
    int count = 0;
    for (int x : arr) {
        int comp = target - x;
        if (freq.count(comp)) {
            if (comp == x) count += freq[x] * (freq[x] - 1) / 2;
            else count += freq[x] * freq[comp];
        }
        freq[x] = 0;
    }
    return count;
}

