    for (int x : arr) freq.put(x, freq.getOrDefault(x, 0) + 1);
    int count = 0;
    Set<Integer> seen = new HashSet<>();
    for (int x : arr) {
        int comp = target - x;
        if (freq.containsKey(comp)) {
            if (comp == x) count += freq.get(x) * (freq.get(x) - 1) / 2;
            else if (!seen.contains(comp)) count += freq.get(x) * freq.get(comp);
        }
        seen.add(x);
    }
    return count;
}

