def common_elements_matrix(matrix):
    from collections import Counter
    if not matrix:
        return []
    n = len(matrix)
    freq = Counter(matrix[0])
    for i in range(1, n):
        row_freq = Counter(matrix[i])
        for key in list(freq.keys()):
            if key not in row_freq:
                del freq[key]
            else:
                freq[key] = min(freq[key], row_freq[key])
