        for (int x : matrix[i]) rowFreq[x]++;
        for (auto it = freq.begin(); it != freq.end(); ) {
            if (rowFreq.count(it->first) == 0)
                it = freq.erase(it);
            else {
                it->second = min(it->second, rowFreq[it->first]);
                ++it;
