#include <string>
#include <array>
using namespace std;

bool isValidShuffle(string s1, string s2, string result) {
    if (result.size() != s1.size() + s2.size()) return false;
    array<int, 256> freq{};
    for (char c : s1) freq[c]++;
    for (char c : s2) freq[c]++;
    for (char c : result) freq[c]--;
    for (int i = 0; i < 256; i++)
        if (freq[i] != 0) return false;
    return true;
}

