    for (char c : s1.toCharArray()) freq[c]++;
    for (char c : s2.toCharArray()) freq[c]++;
    for (char c : result.toCharArray()) freq[c]--;
    for (int f : freq)
        if (f != 0) return false;
    return true;
}

