def count_and_say(n: int) -> str:
    if n == 1:
        return "1"
    prev = count_and_say(n - 1)
    result = []
    i = 0
    while i < len(prev):
        count = 1
        while i + count < len(prev) and prev[i] == prev[i + count]:
            count += 1
        result.append(str(count) + prev[i])
        i += count
    return ''.join(result)

