def longest_palindrome(s: str) -> str:
    if not s:
        return ""
    start, max_len = 0, 1
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return r - l - 1
    for i in range(len(s)):
        odd = expand(i, i)
        even = expand(i, i + 1)
        cur_len = max(odd, even)
        if cur_len > max_len:
            max_len = cur_len
            start = i - (cur_len - 1) // 2
    return s[start:start + max_len]

