#include <string>
using namespace std;

string longestPalindrome(string s) {
    int start = 0, maxLen = 1;
    auto expand = [&](int l, int r) {
        while (l >= 0 && r < s.size() && s[l] == s[r]) {
            l--; r++;
        }
        return r - l - 1;
    };
    for (int i = 0; i < s.size(); i++) {
        int odd = expand(i, i);
        int even = expand(i, i + 1);
        int curLen = max(odd, even);
        if (curLen > maxLen) {
            maxLen = curLen;
            start = i - (curLen - 1) / 2;
        }
    }
    return s.substr(start, maxLen);
}

