def permutations(s: str) -> list:
    result = []
    chars = list(s)
    def backtrack(l, r):
        if l == r:
            result.append(''.join(chars))
        else:
            for i in range(l, r + 1):
                chars[l], chars[i] = chars[i], chars[l]
                backtrack(l + 1, r)
                chars[l], chars[i] = chars[i], chars[l]
    backtrack(0, len(chars) - 1)
    return result

