#include <string>
#include <vector>
#include <algorithm>
using namespace std;

void permute(string& s, int l, int r, vector<string>& result) {
    if (l == r) {
        result.push_back(s);
        return;
    }
    for (int i = l; i <= r; i++) {
        swap(s[l], s[i]);
        permute(s, l + 1, r, result);
        swap(s[l], s[i]);
    }
}

