public static List<String> permutations(String s) {
    List<String> result = new ArrayList<>();
    char[] chars = s.toCharArray();
    backtrack(chars, 0, result);
    return result;
}
private static void backtrack(char[] chars, int l, List<String> result) {
    if (l == chars.length) {
        result.add(new String(chars));
        return;
    }
    for (int i = l; i < chars.length; i++) {
        char tmp = chars[l]; chars[l] = chars[i]; chars[i] = tmp;
        backtrack(chars, l + 1, result);
        tmp = chars[l]; chars[l] = chars[i]; chars[i] = tmp;
    }
}

