def word_wrap(words: list, k: int) -> int:
    n = len(words)
    INF = float('inf')
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        length = 0
        for j in range(i, n):
            length += len(words[j])
            if j > i:
                length += 1
            if length <= k:
                cost[i][j] = (k - length) ** 2
            else:
                cost[i][j] = INF
    dp = [INF] * (n + 1)
    dp[n] = 0
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if cost[i][j] != INF:
                dp[i] = min(dp[i], cost[i][j] + dp[j + 1])
    return dp[0]

def print_solution(words, k):
    n = len(words)
    INF = float('inf')
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        length = 0
        for j in range(i, n):
            length += len(words[j])
            if j > i:
                length += 1
            cost[i][j] = (k - length) ** 2 if length <= k else INF
    dp = [INF] * (n + 1)
    dp[n] = 0
    for i in range(n - 1, -1, -1):
        for j in range(i, n):
            if cost[i][j] != INF:
                dp[i] = min(dp[i], cost[i][j] + dp[j + 1])
    result = []
    i = 0
    while i < n:
        for j in range(i, n):
            if j == n - 1 or dp[i] == cost[i][j] + dp[j + 1]:
                result.append(' '.join(words[i:j + 1]))
                i = j + 1
                break
    return result

