#include <climits>
#include <iostream>
using namespace std;

int wordWrap(const vector<string>& words, int k) {
    int n = words.size();
    vector<vector<int>> cost(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++) {
        int len = 0;
        for (int j = i; j < n; j++) {
            len += words[j].size() + (j > i ? 1 : 0);
            cost[i][j] = len <= k ? (k - len) * (k - len) : INT_MAX;
        }
    }
    vector<int> dp(n + 1, INT_MAX);
    dp[n] = 0;
    for (int i = n - 1; i >= 0; i--)
        for (int j = i; j < n; j++)
            if (cost[i][j] != INT_MAX)
                dp[i] = min(dp[i], cost[i][j] + dp[j + 1]);
    return dp[0];
}

