#include <string>
#include <algorithm>
using namespace std;

string nextGreaterNumber(string num) {
    int n = num.size(), i = n - 2;
    while (i >= 0 && num[i] >= num[i + 1]) i--;
    if (i < 0) return "";
    int j = n - 1;
    while (num[j] <= num[i]) j--;
    swap(num[i], num[j]);
    reverse(num.begin() + i + 1, num.end());
    return num;
}

