#include <string>
#include <vector>
using namespace std;

vector<int> rabinKarp(string text, string pattern) {
    int d = 256, q = 101;
    int n = text.size(), m = pattern.size();
    if (m > n) return {};
    int h = 1;
    for (int i = 0; i < m - 1; i++) h = (h * d) % q;
    int ph = 0, th = 0;
    for (int i = 0; i < m; i++) {
        ph = (d * ph + pattern[i]) % q;
        th = (d * th + text[i]) % q;
    }
    vector<int> result;
    for (int i = 0; i <= n - m; i++) {
        if (ph == th && text.substr(i, m) == pattern)
            result.push_back(i);
        if (i < n - m) {
            th = (d * (th - text[i] * h) + text[i + m]) % q;
            if (th < 0) th += q;
        }
    }
    return result;
}

