    List<Integer> result = new ArrayList<>();
    if (m > n) return result;
    int h = 1;
    for (int i = 0; i < m - 1; i++) h = (h * d) % q;
    int ph = 0, th = 0;
    for (int i = 0; i < m; i++) {
        ph = (d * ph + pattern.charAt(i)) % q;
        th = (d * th + text.charAt(i)) % q;
    }
    for (int i = 0; i <= n - m; i++) {
        if (ph == th && text.substring(i, i + m).equals(pattern))
            result.add(i);
        if (i < n - m) {
            th = (d * (th - text.charAt(i) * h) + text.charAt(i + m)) % q;
            if (th < 0) th += q;
        }
    }
    return result;
}

