def min_reversals(s: str) -> int:
    if len(s) % 2 != 0:
        return -1
    stack = []
    for ch in s:
        if ch == '{':
            stack.append(ch)
        else:
            if stack and stack[-1] == '{':
                stack.pop()
            else:
                stack.append(ch)
    open_count = stack.count('{')
    close_count = stack.count('}')
    return (open_count + 1) // 2 + (close_count + 1) // 2

