#include <string>
#include <stack>
using namespace std;

int minReversals(string s) {
    if (s.size() % 2) return -1;
    stack<char> st;
    for (char c : s) {
        if (c == '{') st.push(c);
        else if (!st.empty() && st.top() == '{') st.pop();
        else st.push(c);
    }
    int open = 0, close = 0;
    while (!st.empty()) {
        if (st.top() == '{') open++;
        else close++;
        st.pop();
    }
    return (open + 1) / 2 + (close + 1) / 2;
}

