def count_palindromic_subseq(s: str) -> int:
    n = len(s)
    MOD = 10**9 + 7
    cps = [[0] * n for _ in range(n)]
    for i in range(n):
        cps[i][i] = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                cps[i][j] = (cps[i + 1][j] + cps[i][j - 1] + 1) % MOD
            else:
                cps[i][j] = (cps[i + 1][j] + cps[i][j - 1] - cps[i + 1][j - 1]) % MOD
    return cps[0][n - 1] % MOD

