def count_occurrences(grid: list, word: str) -> int:
    if not grid or not word:
        return 0
    rows, cols = len(grid), len(grid[0])
    count = [0]
    def dfs(r, c, idx):
        if idx == len(word):
            count[0] += 1
            return
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return
        if grid[r][c] != word[idx]:
            return
        temp = grid[r][c]
        grid[r][c] = '#'  # mark visited
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            dfs(r + dr, c + dc, idx + 1)
        grid[r][c] = temp  # restore
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == word[0]:
                dfs(r, c, 0)
    return count[0]

