#include <string>
#include <vector>
using namespace std;

void backtrack(string& s, int start, vector<string>& parts, vector<string>& result) {
    if (parts.size() == 4) {
        if (start == s.size())
            result.push_back(parts[0]+"."+parts[1]+"."+parts[2]+"."+parts[3]);
        return;
    }
    for (int len = 1; len <= 3 && start + len <= s.size(); len++) {
        string part = s.substr(start, len);
        if (part.size() > 1 && part[0] == '0') break;
        if (stoi(part) > 255) break;
        parts.push_back(part);
        backtrack(s, start + len, parts, result);
        parts.pop_back();
    }
}

vector<string> restoreIPAddresses(string s) {
    vector<string> result, parts;
    backtrack(s, 0, parts, result);
    return result;
}

