def rearrange(s: str) -> str:
    from collections import Counter
    freq = Counter(s)
    max_char = max(freq, key=freq.get)
    max_count = freq[max_char]
    n = len(s)
    if max_count > (n + 1) // 2:
        return ""
    result = [''] * n
    idx = 0
    for _ in range(max_count):
        result[idx] = max_char
        idx += 2
    freq[max_char] = 0
    for ch, count in freq.items():
        for _ in range(count):
            if idx >= n:
                idx = 1
            result[idx] = ch
            idx += 2
    return ''.join(result)

