int minCharsForPalindrome(string s) {
    string combined = s + "$" + string(s.rbegin(), s.rend());
    int n = combined.size();
    vector<int> lps(n, 0);
    int len = 0, i = 1;
    while (i < n) {
        if (combined[i] == combined[len]) {
            lps[i++] = ++len;
        } else if (len) {
            len = lps[len - 1];
        } else {
            lps[i++] = 0;
        }
    }
    return s.size() - lps.back();
}

