string removeAdjDuplicates(string s) {
    vector<pair<char,int>> stack;
    for (char c : s) {
        if (!stack.empty() && stack.back().first == c)
            stack.back().second++;
        else
            stack.push_back({c, 1});
    }
    string result = "";
    for (auto& [ch, cnt] : stack)
        if (cnt == 1) result += ch;
    return result;
}

