def transform_string(a: str, b: str) -> int:
    from collections import Counter
    if Counter(a) != Counter(b):
        return -1
    n = len(a)
    a, b = list(a), list(b)
    i, j = n - 1, n - 1
    result = 0
    while i >= 0:
        if a[i] != b[j]:
            result += 1
            while i >= 0 and a[i] != b[j]:
                i -= 1
        i -= 1
        j -= 1
    return result

