    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

class Solution {
public:
    ListNode* getTail(ListNode* node) {
        while (node && node->next) node = node->next;
        return node;
    }
    ListNode* partition(ListNode* head, ListNode* end, ListNode** newHead, ListNode** newEnd) {
        ListNode* pivot = end;
        ListNode* prev = nullptr;
        ListNode* curr = head;
        ListNode* tail = end;
        while (curr != pivot) {
            if (curr->val < pivot->val) {
                if (!(*newHead)) *newHead = curr;
                prev = curr;
                curr = curr->next;
            } else {
                if (prev) prev->next = curr->next;
                ListNode* tmp = curr->next;
                curr->next = nullptr;
                tail->next = curr;
                tail = curr;
                curr = tmp;
            }
        }
        if (!(*newHead)) *newHead = pivot;
        *newEnd = tail;
        return pivot;
    }
    ListNode* quickSortRecur(ListNode* head, ListNode* end) {
        if (!head || head == end) return head;
        ListNode *newHead = nullptr, *newEnd = nullptr;
        ListNode* pivot = partition(head, end, &newHead, &newEnd);
        if (newHead != pivot) {
            ListNode* tmp = newHead;
            while (tmp->next != pivot) tmp = tmp->next;
            tmp->next = nullptr;
            newHead = quickSortRecur(newHead, tmp);
            tmp = getTail(newHead);
            tmp->next = pivot;
        }
        pivot->next = quickSortRecur(pivot->next, newEnd);
        return newHead;
    }
    ListNode* sortList(ListNode* head) {
        if (!head || !head->next) return head;
        ListNode* end = getTail(head);
        return quickSortRecur(head, end);
    }
};

