class Solution {
public:
    Node* sortKSortedDLL(Node* head, int k) {
        if (!head) return head;
        auto cmp = [](Node* a, Node* b) { return a->val > b->val; };
        std::priority_queue<Node*, std::vector<Node*>, decltype(cmp)> minHeap(cmp);
        Node* curr = head;
        for (int i = 0; i <= k && curr; i++) {
            minHeap.push(curr);
            curr = curr->next;
        }
        Node dummy(0);
        Node* tail = &dummy;
        while (!minHeap.empty()) {
            Node* node = minHeap.top();
            minHeap.pop();
            tail->next = node;
            node->prev = tail;
            tail = node;
            if (curr) {
                minHeap.push(curr);
                curr = curr->next;
            }
        }
        tail->next = nullptr;
        return dummy.next;
    }
};

