    DLLNode* prev;
    DLLNode* next;
    DLLNode(char c) : ch(c), prev(nullptr), next(nullptr) {}
};

class Solution {
public:
    string firstNonRepeating(string stream) {
        DLLNode* inDLL[256] = {};
        bool repeated[256] = {};
        DLLNode* head = nullptr;
        string result;
        for (char ch : stream) {
            unsigned char c = ch;
            if (repeated[c]) {
                result += head ? string(1, head->ch) : '#';
                continue;
            }
            if (!inDLL[c]) {
                DLLNode* node = new DLLNode(ch);
                inDLL[c] = node;
                if (!head) {
                    head = node;
                } else {
                    DLLNode* tail = head;
                    while (tail->next) tail = tail->next;
                    tail->next = node;
                    node->prev = tail;
                }
            } else {
                DLLNode* node = inDLL[c];
                if (node->prev) node->prev->next = node->next;
                else head = node->next;
                if (node->next) node->next->prev = node->prev;
                inDLL[c] = nullptr;
                repeated[c] = true;
            }
            result += head ? string(1, head->ch) : '#';
        }
        return result;
    }
};

