int goldMine(vector<vector<int>>& gold) {
    int m = gold.size(), n = gold[0].size();
    vector<vector<int>> dp(m, vector<int>(n, 0));
    for (int j = n-1; j >= 0; j--)
        for (int i = 0; i < m; i++) {
            int r = (j < n-1) ? dp[i][j+1] : 0;
            int ru = (i > 0 && j < n-1) ? dp[i-1][j+1] : 0;
            int rd = (i < m-1 && j < n-1) ? dp[i+1][j+1] : 0;
            dp[i][j] = gold[i][j] + max({r, ru, rd});
        }
    int ans = 0;
    for (int i = 0; i < m; i++) ans = max(ans, dp[i][0]);
    return ans;
}

