def countSubseq(arr, k):
    if k <= 1: return 0
    dp = [0] * k
    dp[1] = 1
    for num in arr:
        if num >= k: continue
        cdp = dp[:]
        for j in range(k - 1, num - 1, -1):
            cdp[j] += dp[j - num]
        dp = cdp
    return sum(dp[1:])

