int countSubseq(vector<int>& arr, int k) {
    if (k <= 1) return 0;
    vector<int> dp(k, 0);
    dp[1] = 1;
    for (int num : arr) {
        if (num >= k) continue;
        vector<int> cdp = dp;
        for (int j = k - 1; j >= num; j--)
            cdp[j] += dp[j - num];
        dp = cdp;
    }
    return accumulate(dp.begin() + 1, dp.end(), 0);
}

