        int[] cdp = dp.clone();
        for (int j = k - 1; j >= num; j--)
            cdp[j] += dp[j - num];
        dp = cdp;
    }
    int total = 0;
    for (int i = 1; i < k; i++) total += dp[i];
    return total;
}

