def eggDrop(eggs, floors):
    dp = [[0]*(floors+1) for _ in range(eggs+1)]
    for j in range(1, floors+1):
        dp[1][j] = j
    for i in range(2, eggs+1):
        for j in range(1, floors+1):
            dp[i][j] = j
            lo, hi = 1, j
            while lo <= hi:
                mid = (lo + hi) // 2
                broken = dp[i-1][mid-1]
                not_broken = dp[i][j-mid]
                trials = 1 + max(broken, not_broken)
                if broken < not_broken:
                    lo = mid + 1
                elif broken > not_broken:
                    hi = mid - 1
                else:
                    dp[i][j] = trials
                    break
            if lo > hi:
                dp[i][j] = 1 + max(dp[i-1][lo-1], dp[i][j-lo])
    return dp[eggs][floors]

