    n = len(arr)
    dp = [[-1]*n for _ in range(n)]
    def solve(i, j):
        if i >= j: return 0
        if dp[i][j] != -1: return dp[i][j]
        if arr[j] - arr[i] <= k:
            dp[i][j] = 0
