    Arrays.sort(arr);
    int n = arr.length;
    int[][] dp = new int[n][n];
    for (int[] row : dp) Arrays.fill(row, -1);
    return solve(arr, dp, 0, n-1, k);
}
private int solve(int[] arr, int[][] dp, int i, int j, int k) {
    if (i >= j) return 0;
    if (dp[i][j] != -1) return dp[i][j];
    if (arr[j] - arr[i] <= k) return dp[i][j] = 0;
    return dp[i][j] = 1 + Math.min(solve(arr,dp,i+1,j,k), solve(arr,dp,i,j-1,k));
}

