    sort(jobs.begin(), jobs.end(), [](auto a, auto b){ return get<1>(a) < get<1>(b); });
    int n = jobs.size();
    vector<int> dp(n);
    dp[0] = get<2>(jobs[0]);
    for (int i = 1; i < n; i++) {
        int incl = get<2>(jobs[i]);
        int lo = upper_bound(jobs.begin(), jobs.begin()+i, get<0>(jobs[i]),
            [](int val, auto j){ return val < get<1>(j); }) - jobs.begin() - 1;
        if (lo >= 0) incl += dp[lo];
        dp[i] = max(dp[i-1], incl);
    }
    return dp[n-1];
}

