def optimalBST(keys, freq):
    n = len(keys)
    dp = [[0.0]*n for _ in range(n)]
    for i in range(n):
        dp[i][i] = freq[i]
    for L in range(2, n + 1):
        for i in range(n - L + 1):
            j = i + L - 1
            dp[i][j] = float('inf')
            freq_sum = sum(freq[k] for k in range(i, j + 1))
