            for (int i = 0; i < m; i++) temp[i] += mat[i][right];
            int currMax = temp[0], maxEnd = temp[0];
            for (int i = 1; i < m; i++) {
                maxEnd = Math.max(temp[i], maxEnd + temp[i]);
                currMax = Math.max(currMax, maxEnd);
            }
            maxSum = Math.max(maxSum, currMax);
        }
    }
    return maxSum;
}

