def maxProfitK(prices, k):
    n = len(prices)
    if n < 2 or k == 0: return 0
    if k >= n // 2:
        return sum(max(0, prices[i]-prices[i-1]) for i in range(1, n))
    dp = [[0]*n for _ in range(k+1)]
    for t in range(1, k+1):
        max_diff = -prices[0]
        for j in range(1, n):
            dp[t][j] = max(dp[t][j-1], prices[j] + max_diff)
            max_diff = max(max_diff, dp[t-1][j] - prices[j])
    return dp[k][n-1]

