#include <iostream>
#include <vector>
#include <queue>
using namespace std;
int searchMaze(vector<vector<int>>& maze, pair<int,int> start, pair<int,int> end) {
    int rows = maze.size(), cols = maze[0].size();
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    queue<pair<pair<int,int>, int>> q;
    q.push({start, 0});
    visited[start.first][start.second] = true;
    int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
    while (!q.empty()) {
        auto [pos, dist] = q.front(); q.pop();
        if (pos == end) return dist;
        for (auto& d : dirs) {
            int nr = pos.first + d[0], nc = pos.second + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && maze[nr][nc] == 1 && !visited[nr][nc]) {
                visited[nr][nc] = true;
                q.push({{nr, nc}, dist + 1});
            }
        }
    }
    return -1;
}
int main() {
    vector<vector<int>> maze = {{1,0,0,0},{1,1,0,1},{0,1,0,0},{1,1,1,1}};
    cout << "Shortest path: " << searchMaze(maze, {0,0}, {3,3}) << endl;
    return 0;
}

