    vector<vector<bool>> visited(n, vector<bool>(n, false));
    queue<pair<pair<int,int>, int>> q;
    q.push({start, 0}); visited[start.first][start.second] = true;
    int moves[8][2] = {{-2,-1},{-2,1},{-1,-2},{-1,2},{1,-2},{1,2},{2,-1},{2,1}};
    while (!q.empty()) {
        auto [pos, dist] = q.front(); q.pop();
        for (auto& m : moves) {
            int nr = pos.first + m[0], nc = pos.second + m[1];
            if (nr == end.first && nc == end.second) return dist + 1;
            if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc]) {
                visited[nr][nc] = true;
                q.push({{nr, nc}, dist + 1});
            }
        }
    }
    return -1;
}
int main() { cout << minStepKnight({0,0}, {7,7}, 8) << endl; return 0; }

