import java.util.*;
class Solution {
    static int minStepKnight(int[] start, int[] end, int n) {
        if (start[0] == end[0] && start[1] == end[1]) return 0;
        boolean[][] visited = new boolean[n][n];
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{start[0], start[1], 0});
        visited[start[0]][start[1]] = true;
        int[][] moves = {{-2,-1},{-2,1},{-1,-2},{-1,2},{1,-2},{1,2},{2,-1},{2,1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int[] m : moves) {
                int nr = cur[0]+m[0], nc = cur[1]+m[1];
                if (nr == end[0] && nc == end[1]) return cur[2]+1;
                if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc]) {
                    visited[nr][nc] = true; q.add(new int[]{nr, nc, cur[2]+1});
                }
            }
        }
        return -1;
    }
    public static void main(String[] args) { System.out.println(minStepKnight(new int[]{0,0}, new int[]{7,7}, 8)); }
}

