int wordLadder(string beginWord, string endWord, vector<string>& wordList) {
    unordered_set<string> wordSet(wordList.begin(), wordList.end());
    if (!wordSet.count(endWord)) return 0;
    queue<pair<string,int>> q;
    q.push({beginWord, 1});
    unordered_set<string> visited = {beginWord};
    while (!q.empty()) {
        auto [word, len] = q.front(); q.pop();
        for (int i = 0; i < (int)word.size(); i++) {
            string nw = word;
            for (char c = 'a'; c <= 'z'; c++) {
                nw[i] = c;
                if (nw == endWord) return len + 1;
                if (wordSet.count(nw) && !visited.count(nw)) {
                    visited.insert(nw); q.push({nw, len + 1});
                }
            }
        }
    }
    return 0;
}
int main() {
    vector<string> wl = {"hot","dot","dog","lot","log","cog"};
    cout << wordLadder("hit", "cog", wl) << endl;
    return 0;
}

