import java.util.*;
class Solution {
    static int wordLadder(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) return 0;
        Queue<String[]> q = new LinkedList<>();
        q.add(new String[]{beginWord, "1"});
        Set<String> visited = new HashSet<>(); visited.add(beginWord);
        while (!q.isEmpty()) {
            String[] cur = q.poll();
            String word = cur[0]; int len = Integer.parseInt(cur[1]);
            char[] arr = word.toCharArray();
            for (int i = 0; i < arr.length; i++) {
                char orig = arr[i];
                for (char c = 'a'; c <= 'z'; c++) {
                    arr[i] = c;
                    String nw = new String(arr);
                    if (nw.equals(endWord)) return len + 1;
                    if (wordSet.contains(nw) && !visited.contains(nw)) {
                        visited.add(nw); q.add(new String[]{nw, String.valueOf(len+1)});
                    }
                }
                arr[i] = orig;
            }
        }
        return 0;
    }
    public static void main(String[] args) {
        System.out.println(wordLadder("hit","cog",Arrays.asList("hot","dot","dog","lot","log","cog")));
    }
}

