import java.util.*;
class Solution {
    static int[] dijkstra(List<List<int[]>> graph, int src, int V) {
        int[] dist = new int[V]; Arrays.fill(dist, Integer.MAX_VALUE);
        dist[src] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a,b)->a[1]-b[1]);
        pq.add(new int[]{src, 0});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int u = cur[0], d = cur[1];
            if (d > dist[u]) continue;
            for (int[] edge : graph.get(u)) {
                int v = edge[0], w = edge[1];
                if (dist[v] > dist[u] + w) { dist[v] = dist[u]+w; pq.add(new int[]{v, dist[v]}); }
            }
        }
        return dist;
    }
    public static void main(String[] args) {
        List<List<int[]>> g = new ArrayList<>();
        for (int i = 0; i < 4; i++) g.add(new ArrayList<>());
        g.get(0).add(new int[]{1,4}); g.get(0).add(new int[]{2,1});
        g.get(1).add(new int[]{3,1}); g.get(2).add(new int[]{1,2}); g.get(2).add(new int[]{3,5});
        System.out.println(Arrays.toString(dijkstra(g, 0, 4)));
    }
}

