def min_time(n, deps):
    adj = [[] for _ in range(n+1)]
    indegree = [0]*(n+1)
    for u, v in deps:
        adj[u].append(v); indegree[v] += 1
    job = [0]*(n+1)
    q = deque()
    for i in range(1, n+1):
        if indegree[i] == 0: q.append(i); job[i] = 1
    while q:
        cur = q.popleft()
        for nb in adj[cur]:
            indegree[nb] -= 1
            if indegree[nb] == 0: job[nb] = job[cur]+1; q.append(nb)
    return job[1:]

