vector<int> minTime(int n, vector<pair<int,int>>& deps) {
    vector<vector<int>> adj(n+1); vector<int> indegree(n+1,0), job(n+1,0);
    for (auto& [u,v] : deps) { adj[u].push_back(v); indegree[v]++; }
    queue<int> q;
    for (int i = 1; i <= n; i++) if (indegree[i]==0) { q.push(i); job[i]=1; }
    while (!q.empty()) {
        int cur = q.front(); q.pop();
        for (int v : adj[cur]) if (--indegree[v]==0) { job[v]=job[cur]+1; q.push(v); }
    }
    return vector<int>(job.begin()+1, job.end());
}
