import java.util.*;
class Solution {
    static List<Integer> minTime(int n, int[][] deps) {
        List<List<Integer>> adj = new ArrayList<>();
        int[] indegree = new int[n+1], job = new int[n+1];
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] d : deps) { adj.get(d[0]).add(d[1]); indegree[d[1]]++; }
        Queue<Integer> q = new LinkedList<>();
        for (int i = 1; i <= n; i++) if (indegree[i]==0) { q.add(i); job[i]=1; }
        while (!q.isEmpty()) {
            int cur = q.poll();
            for (int v : adj.get(cur)) if (--indegree[v]==0) { job[v]=job[cur]+1; q.add(v); }
        }
        return Arrays.stream(job,1,n+1).boxed().toList();
    }
    public static void main(String[] args) {
        System.out.println(minTime(6, new int[][]{{1,2},{2,3},{1,3},{4,5},{4,6},{5,6}}));
    }
}

