from collections import defaultdict, deque

def alien_order(words):
    adj = defaultdict(set)
    chars = set(''.join(words))
    for w1, w2 in zip(words, words[1:]):
        for c1, c2 in zip(w1, w2):
            if c1 != c2: adj[c1].add(c2); break
    indegree = {c: 0 for c in chars}
    for c in adj:
        for n in adj[c]: indegree[n] += 1
    q = deque([c for c in chars if indegree[c] == 0])
    order = []
    while q:
        c = q.popleft(); order.append(c)
        for n in adj[c]:
            indegree[n] -= 1
            if indegree[n] == 0: q.append(n)
    return ''.join(order) if len(order) == len(chars) else ""

