#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <unordered_map>
#include <unordered_set>
using namespace std;
string alienOrder(vector<string>& words) {
    unordered_map<char, unordered_set<char>> adj;
    unordered_map<char, int> indegree;
    for (auto& w : words) for (char c : w) { adj[c]; indegree[c]; }
    for (int i = 0; i+1 < words.size(); i++) {
        string w1=words[i], w2=words[i+1];
        for (int j=0; j<min(w1.size(),w2.size()); j++)
            if (w1[j]!=w2[j]) { adj[w1[j]].insert(w2[j]); break; }
    }
    for (auto& [c,neighbors] : adj) for (char n : neighbors) indegree[n]++;
    queue<char> q;
    for (auto& [c,deg] : indegree) if (deg==0) q.push(c);
    string order;
    while (!q.empty()) { char c=q.front(); q.pop(); order+=c;
        for (char n : adj[c]) if (--indegree[n]==0) q.push(n);
    }
    return order.size()==indegree.size() ? order : "";
}
int main() {
    vector<string> words = {"wrt","wrf","er","ett","rftt"};
    cout << alienOrder(words) << endl;
    return 0;
}

