import java.util.*;
class Solution {
    static String alienOrder(String[] words) {
        Map<Character,Set<Character>> adj = new HashMap<>();
        Map<Character,Integer> indegree = new HashMap<>();
        for (String w : words) for (char c : w.toCharArray()) { adj.putIfAbsent(c,new HashSet<>()); indegree.putIfAbsent(c,0); }
        for (int i = 0; i+1 < words.length; i++) {
            String w1=words[i], w2=words[i+1];
            for (int j=0; j<Math.min(w1.length(),w2.length()); j++)
                if (w1.charAt(j)!=w2.charAt(j)) { adj.get(w1.charAt(j)).add(w2.charAt(j)); break; }
        }
        for (var e : adj.entrySet()) for (char n : e.getValue()) indegree.merge(n,1,Integer::sum);
        Queue<Character> q = new LinkedList<>();
        for (var e : indegree.entrySet()) if (e.getValue()==0) q.add(e.getKey());
        StringBuilder order = new StringBuilder();
        while (!q.isEmpty()) { char c=q.poll(); order.append(c);
            for (char n : adj.get(c)) if (indegree.merge(n,-1,Integer::sum)==0) q.add(n);
        }
        return order.length()==indegree.size() ? order.toString() : "";
    }
    public static void main(String[] args) {
        System.out.println(alienOrder(new String[]{"wrt","wrf","er","ett","rftt"}));
    }
}

