#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
struct UnionFind {
    vector<int> parent, rank;
    UnionFind(int n) : parent(n), rank(n,0) { for (int i=0;i<n;i++) parent[i]=i; }
    int find(int x) { return parent[x]==x ? x : parent[x]=find(parent[x]); }
    bool unite(int x, int y) {
        int px=find(x), py=find(y);
        if (px==py) return false;
        if (rank[px]<rank[py]) swap(px,py);
        parent[py]=px; if (rank[px]==rank[py]) rank[px]++;
        return true;
    }
};
int main() {
    vector<tuple<int,int,int>> edges = {{0,1,10},{0,2,6},{0,3,5},{1,3,15},{2,3,4}};
    sort(edges.begin(), edges.end(), [](auto& a, auto& b) { return get<2>(a)<get<2>(b); });
    UnionFind uf(4); vector<tuple<int,int,int>> mst;
    for (auto& [u,v,w] : edges) if (uf.unite(u,v)) mst.push_back({u,v,w});
    for (auto& [u,v,w] : mst) cout << u << "-" << v << ":" << w << " ";
    return 0;
}

