import heapq

def prim(graph, V):
    visited = [False]*V
    pq = [(0, 0, -1)]; mst = []; total = 0
    while pq and len(mst) < V:
        weight, u, parent = heapq.heappop(pq)
        if visited[u]: continue
        visited[u] = True; total += weight
        if parent != -1: mst.append((parent, u, weight))
        for v, w in graph[u]:
            if not visited[v]: heapq.heappush(pq, (w, v, u))
    return mst, total

