def count_spanning_trees(V, graph):
    laplacian = [[0]*V for _ in range(V)]
    for i in range(V):
        degree = sum(graph[i])
        laplacian[i][i] = degree
        for j in range(V):
            if graph[i][j]: laplacian[i][j] = -graph[i][j]
    minor = [row[1:] for row in laplacian[1:]]
    n = len(minor)
    result = 1.0
    for i in range(n):
        pivot = i
        for j in range(i+1, n):
            if abs(minor[j][i]) > abs(minor[pivot][i]): pivot = j
        minor[i], minor[pivot] = minor[pivot], minor[i]
        if abs(minor[i][i]) < 1e-10: return 0
        result *= minor[i][i]
        for j in range(i+1, n):
            f = minor[j][i] / minor[i][i]
            for k in range(i+1, n): minor[j][k] -= f * minor[i][k]
    return int(round(result))

