#include <iostream>
#include <vector>
#include <climits>
using namespace std;
int tsp(vector<vector<int>>& graph, int n) {
    vector<vector<int>> memo(1<<n, vector<int>(n,-1));
    auto dp = [&](auto&& self, int mask, int pos) -> int {
        if (mask==(1<<n)-1) return graph[pos][0];
        if (memo[mask][pos]!=-1) return memo[mask][pos];
        int ans=INT_MAX;
        for (int c=0;c<n;c++) if (!(mask&(1<<c)))
            ans=min(ans, graph[pos][c]+self(self, mask|(1<<c), c));
        return memo[mask][pos]=ans;
    };
    return dp(dp, 1, 0);
}
int main() {
    vector<vector<int>> g={{0,10,15,20},{10,0,35,25},{15,35,0,30},{20,25,30,0}};
    cout << "Min cost: " << tsp(g,4) << endl;
    return 0;
}

