int snakeLadder(int n, vector<pair<int,int>>& moves) {
    vector<int> board(n+1,-1);
    for (auto& [s,d] : moves) board[s]=d;
    vector<bool> visited(n+1,false);
    queue<pair<int,int>> q; q.push({1,0}); visited[1]=true;
    while (!q.empty()) {
        auto [cell,dist] = q.front(); q.pop();
        for (int dice=1;dice<=6;dice++) {
            int nxt=cell+dice; if (nxt>n) continue;
            if (board[nxt]!=-1) nxt=board[nxt];
            if (nxt==n) return dist+1;
            if (!visited[nxt]) { visited[nxt]=true; q.push({nxt,dist+1}); }
        }
    }
    return -1;
}
int main() {
    vector<pair<int,int>> moves={{2,15},{14,25},{17,7},{9,28},{24,16},{20,6},{29,1},{3,22}};
    cout << snakeLadder(30,moves) << endl;
    return 0;
}

