import java.util.*;
class Solution {
    static int snakeLadder(int n, int[][] moves) {
        int[] board = new int[n+1]; Arrays.fill(board,-1);
        for (int[] m : moves) board[m[0]]=m[1];
        boolean[] visited = new boolean[n+1];
        Queue<int[]> q = new LinkedList<>(); q.add(new int[]{1,0}); visited[1]=true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int dice=1;dice<=6;dice++) {
                int nxt=cur[0]+dice; if (nxt>n) continue;
                if (board[nxt]!=-1) nxt=board[nxt];
                if (nxt==n) return cur[1]+1;
                if (!visited[nxt]) { visited[nxt]=true; q.add(new int[]{nxt,cur[1]+1}); }
            }
        }
        return -1;
    }
    public static void main(String[] args) {
        System.out.println(snakeLadder(30, new int[][]{{2,15},{14,25},{17,7},{9,28},{24,16},{20,6},{29,1},{3,22}}));
