from collections import deque

def is_bipartite(graph, V):
    color = [-1]*V
    for start in range(V):
        if color[start] != -1: continue
        color[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if color[v] == -1: color[v] = 1-color[u]; q.append(v)
                elif color[v] == color[u]: return False
    return True

