import java.util.*;
class Solution {
    static void dfs(int v, List<List<int[]>> adj, boolean[] vis, Stack<Integer> topo) {
        vis[v]=true; for (int[] e:adj.get(v)) if (!vis[e[0]]) dfs(e[0],adj,vis,topo); topo.push(v);
    }
    static List<Integer> longestPath(int V, int[][] edges, int src) {
        List<List<int[]>> adj=new ArrayList<>();
        for (int i=0;i<V;i++) adj.add(new ArrayList<>());
        for (int[] e:edges) adj.get(e[0]).add(new int[]{e[1],e[2]});
        boolean[] vis=new boolean[V]; Stack<Integer> topo=new Stack<>();
        for (int i=0;i<V;i++) if (!vis[i]) dfs(i,adj,vis,topo);
        int[] dist=new int[V]; Arrays.fill(dist,Integer.MIN_VALUE); dist[src]=0;
        while (!topo.isEmpty()) {
            int u=topo.pop();
            if (dist[u]!=Integer.MIN_VALUE) for (int[] e:adj.get(u))
                dist[e[0]]=Math.max(dist[e[0]],dist[u]+e[1]);
        }
        return Arrays.stream(dist).boxed().toList();
    }
    public static void main(String[] args) {
        System.out.println(longestPath(6,new int[][]{{0,1,5},{0,2,3},{1,3,6},{1,2,2},{2,4,7},{2,5,4},{3,5,1},{4,5,-1}},0));
