    for(int i=0;i<=k;i++) {
        vector<int> tmp=dist;
        for(auto& f:flights)
            if(dist[f[0]]!=INT_MAX && dist[f[0]]+f[2]<tmp[f[1]])
                tmp[f[1]]=dist[f[0]]+f[2];
        dist=tmp;
    }
    return dist[dst]==INT_MAX?-1:dist[dst];
}

