vector<tuple<int,int,int>> minCashFlow(vector<tuple<int,int,int>>& trans) {
    map<int,int> bal;
    for(auto& [u,v,a]:trans){bal[u]+=a;bal[v]-=a;}
    vector<tuple<int,int,int>> steps;
    while(true){
        int mxv=0,mnv=0,mxk=0,mnk=0;
        for(auto& [k,v]:bal){if(v>mxv){mxv=v;mxk=k;}if(v<mnv){mnv=v;mnk=k;}}
        if(mxv==0&&mnv==0) break;
        int s=min(mxv,-mnv);
        steps.push_back({mnk,mxk,s});
        bal[mxk]-=s;bal[mnk]+=s;
    }
    return steps;
}

