        int mxv=0,mnv=0,mxk=0,mnk=0;
        for(var e:bal.entrySet()){if(e.getValue()>mxv){mxv=e.getValue();mxk=e.getKey();}if(e.getValue()<mnv){mnv=e.getValue();mnk=e.getKey();}}
