static Map<Character,String> huffmanCoding(String text) {
    Map<Character,Integer> freq = new HashMap<>();
    for(char c:text) freq.merge(c,1,Integer::sum);
    Map<Character,String> codes = new HashMap<>();
    // Build Huffman tree using PriorityQueue
    PriorityQueue<int[]> pq = new PriorityQueue<>((a,b)->a[0]-b[0]);
    for(var e:freq.entrySet()) pq.add(new int[]{e.getValue(),e.getKey()});
    while(pq.size()>1){int[] l=pq.poll(),r=pq.poll();pq.add(new int[]{l[0]+r[0],0});}
    // Leaf codes would need tree traversal - simplified here
    int idx=0; for(var e:freq.entrySet()) codes.put(e.getKey(),Integer.toBinaryString(++idx));
    return codes;
}

