def waterConnection(houses, pipes):
    parent = list(range(houses+1))
    diameter = [0]*(houses+1)
    def find(x):
        while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
        return x
    for s,e,d in pipes:
        rs,re = find(s),find(e)
        parent[rs]=re
        diameter[re] = d if diameter[re]==0 else min(diameter[re],d)
    # Source = node with in-degree 0 in each component
    result = []
    for i in range(1,houses+1):
        if find(i)==i and diameter[i]>0:
            result.append((i, diameter[i]))
    return result

