    int find(int x){while(par[x]!=x){par[x]=par[par[x]];x=par[x];}return x;}
    for(int[] p:pipes){int rs=find(p[0]),re=find(p[1]);par[rs]=re;diam[re]=diam[re]==0?p[2]:Math.min(diam[re],p[2]);}
    List<int[]> res = new ArrayList<>();
    for(int i=1;i<=n;i++) if(find(i)==i&&diam[i]>0) res.add(new int[]{i,diam[i]});
    return res;
}

