long long maxProductSubset(vector<int>& arr) {
    if(arr.size()==1) return arr[0];
    long long prod=1; int negCnt=0, maxNeg=INT_MIN, zeroCnt=0;
    for(int x:arr){
        if(x==0){zeroCnt++;continue;}
        prod*=x;
        if(x<0){negCnt++;maxNeg=max(maxNeg,x);}
    }
    if(negCnt%2) prod/=maxNeg;
    if(prod==1&&negCnt==0&&zeroCnt) return 0;
    return prod;
}

