    list<int> cache;
    unordered_map<int,list<int>::iterator> mp;
    int faults=0;
    for(int p:pages){
        if(mp.count(p)){cache.erase(mp[p]);cache.push_back(p);mp[p]=prev(cache.end());}
        else{
            faults++;
            if((int)cache.size()==capacity){mp.erase(cache.front());cache.pop_front();}
            cache.push_back(p);mp[p]=prev(cache.end());
        }
    }
    return faults;
}

