    if(s==0&&d>1) return "-1";
    if(s>9*d) return "-1";
    string res(d,'0'); s--;
    for(int i=d-1;i>0;i--){if(s>=9){res[i]='9';s-=9;}else{res[i]='0'+s;s=0;}}
    res[0]='1'+s;
    return res;
}

