static String smallestNumber(int d, int s) {
    if(s==0) return d>1?"-1":"0";
    if(s>9*d) return "-1";
    char[] res = new char[d]; Arrays.fill(res,'0'); s--;
    for(int i=d-1;i>0;i--){if(s>=9){res[i]='9';s-=9;}else{res[i]=(char)('0'+s);s=0;}}
    res[0]=(char)('1'+s);
    return new String(res);
}

