int maxSum(vector<int>& s1, vector<int>& s2, vector<int>& s3) {
    int a=accumulate(s1.begin(),s1.end(),0);
    int b=accumulate(s2.begin(),s2.end(),0);
    int c=accumulate(s3.begin(),s3.end(),0);
    int i=0,j=0,k=0;
    while(!(a==b&&b==c)){
        if(a>=b&&a>=c) a-=s1[i++];
        else if(b>=a&&b>=c) b-=s2[j++];
        else c-=s3[k++];
    }
    return a;
}

