def find_first_and_last(arr, target):
    def bs_left(arr, t):
        lo, hi, res = 0, len(arr) - 1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == t:
                res = mid
                hi = mid - 1
            elif arr[mid] < t:
                lo = mid + 1
            else:
                hi = mid - 1
        return res

    def bs_right(arr, t):
        lo, hi, res = 0, len(arr) - 1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == t:
                res = mid
                lo = mid + 1
            elif arr[mid] < t:
                lo = mid + 1
            else:
                hi = mid - 1
        return res

    return [bs_left(arr, target), bs_right(arr, target)]

