vector<int> findFirstAndLast(vector<int>& arr, int target) {
    int n = arr.size();
    int lo = 0, hi = n - 1, left = -1, right = -1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (arr[mid] == target) { left = mid; hi = mid - 1; }
        else if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    lo = 0; hi = n - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (arr[mid] == target) { right = mid; lo = mid + 1; }
        else if (arr[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return {left, right};
}

