int sqrtInt(int n) {
    if (n < 2) return n;
    int lo = 1, hi = n, ans = 0;
    while (lo <= hi) {
        long long mid = (lo + hi) / 2;
        if (mid * mid == (long long)n) return mid;
        else if (mid * mid < n) { lo = mid + 1; ans = mid; }
        else hi = mid - 1;
    }
    return ans;
}

