static int sqrtInt(int n) {
    if (n < 2) return n;
    int lo = 1, hi = n, ans = 0;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        long m = (long) mid * mid;
        if (m == n) return mid;
        else if (m < n) { lo = mid + 1; ans = mid; }
        else hi = mid - 1;
    }
    return ans;
}

