pair<int,int> findRepeatingMissing(vector<int>& arr) {
    int n = arr.size(), xorVal = 0;
    for (int x : arr) xorVal ^= x;
    for (int i = 1; i <= n; i++) xorVal ^= i;
    int setBit = xorVal & ~(xorVal - 1);
    int x = 0, y = 0;
    for (int val : arr) {
        if (val & setBit) x ^= val; else y ^= val;
    }
    for (int i = 1; i <= n; i++) {
        if (i & setBit) x ^= i; else y ^= i;
    }
    bool xIsDup = false;
    for (int val : arr) if (val == x) { xIsDup = true; break; }
    return xIsDup ? make_pair(x, y) : make_pair(y, x);
}

