static int[] findRepeatingMissing(int[] arr) {
    int n = arr.length, xorVal = 0;
    for (int x : arr) xorVal ^= x;
    for (int i = 1; i <= n; i++) xorVal ^= i;
    int setBit = xorVal & ~(xorVal - 1);
    int x = 0, y = 0;
    for (int v : arr) { if ((v & setBit) != 0) x ^= v; else y ^= v; }
    for (int i = 1; i <= n; i++) { if ((i & setBit) != 0) x ^= i; else y ^= i; }
    boolean xIsDup = false;
    for (int v : arr) if (v == x) { xIsDup = true; break; }
    return xIsDup ? new int[]{x, y} : new int[]{y, x};
}

