def merge_sorted_inplace(arr1, arr2):
    arr1.extend(arr2)
    total = len(arr1)
    gap = (total + 1) // 2
    while gap > 0:
        for i in range(total - gap):
            j = i + gap
            if arr1[i] > arr1[j]:
                arr1[i], arr1[j] = arr1[j], arr1[i]
        gap = (gap + 1) // 2 if gap > 1 else 0
    return arr1

