void mergeSortedInplace(vector<int>& arr1, vector<int>& arr2) {
    arr1.insert(arr1.end(), arr2.begin(), arr2.end());
    int total = arr1.size(), gap = (total+1)/2;
    while (gap > 0) {
        for (int i = 0; i < total-gap; i++)
            if (arr1[i] > arr1[i+gap]) swap(arr1[i], arr1[i+gap]);
        gap = (gap+1)/2;
        if (gap == 1) gap = 0;
    }
}

