static void mergeSortedInplace(int[] arr1, int[] arr2) {
    int[] merged = new int[arr1.length + arr2.length];
    System.arraycopy(arr1, 0, merged, 0, arr1.length);
    System.arraycopy(arr2, 0, merged, arr1.length, arr2.length);
    int total = merged.length, gap = (total+1)/2;
    while (gap > 0) {
        for (int i = 0; i < total-gap; i++)
            if (merged[i] > merged[i+gap]) {
                int t=merged[i]; merged[i]=merged[i+gap]; merged[i+gap]=t;
            }
        gap = (gap+1)/2;
        if (gap == 1) gap = 0;
    }
}

