def find_zero_sum_subarrays(arr):
    from collections import defaultdict
    sum_map = defaultdict(list)
    prefix = 0
    result = []
    for i, x in enumerate(arr):
        prefix += x
        if prefix == 0:
            result.append((0, i))
        for j in sum_map[prefix]:
            result.append((j + 1, i))
        sum_map[prefix].append(i)
    return result

