    vector<pair<int,int>> result;
    for (int i = 0; i < arr.size(); i++) {
        prefix += arr[i];
        if (prefix == 0) result.push_back({0, i});
        for (int j : sumMap[prefix]) result.push_back({j+1, i});
        sumMap[prefix].push_back(i);
    }
    return result;
}

