    for (int i = 0; i < arr.length; i++) {
        prefix += arr[i];
        if (prefix == 0) result.add(new int[]{0, i});
        if (sumMap.containsKey(prefix))
            for (int j : sumMap.get(prefix)) result.add(new int[]{j+1, i});
        sumMap.computeIfAbsent(prefix, k -> new ArrayList<>()).add(i);
    }
    return result;
}

