static int minSwapsToSort(int[] arr) {
    int n = arr.length;
    int[][] indexed = new int[n][2];
    for (int i = 0; i < n; i++) { indexed[i][0] = arr[i]; indexed[i][1] = i; }
    Arrays.sort(indexed, (a,b) -> a[0]-b[0]);
    boolean[] visited = new boolean[n];
    int swaps = 0;
    for (int i = 0; i < n; i++) {
        if (visited[i] || indexed[i][1] == i) continue;
        int cycleSize = 0, j = i;
        while (!visited[j]) { visited[j]=true; j=indexed[j][1]; cycleSize++; }
        swaps += cycleSize - 1;
    }
    return swaps;
}

