vector<pair<int,int>> bishuSoldiers(vector<int>& arr, vector<int>& queries) {
    sort(arr.begin(), arr.end());
    int n = arr.size();
    vector<int> prefix(n+1, 0);
    for (int i = 0; i < n; i++) prefix[i+1] = prefix[i] + arr[i];
    vector<pair<int,int>> results;
    for (int q : queries) {
        int lo=0, hi=n-1, ans=0;
        while (lo <= hi) {
            int mid = (lo+hi)/2;
            if (arr[mid] <= q) { ans=mid+1; lo=mid+1; }
            else hi=mid-1;
        }
        results.push_back({ans, prefix[ans]});
    }
    return results;
}

