def kth_smallest(intervals, k):
    intervals.sort()
    merged = [list(intervals[0])]
    for s, e in intervals[1:]:
        if s <= merged[-1][1] + 1:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    for s, e in merged:
        size = e - s + 1
        if k <= size: return s + k - 1
        k -= size
    return -1

