int kthElement(vector<int>& arr1, vector<int>& arr2, int k) {
    if (arr1.size() > arr2.size()) swap(arr1, arr2);
    int n = arr1.size(), m = arr2.size();
    int lo = max(0, k-m), hi = min(k, n);
    while (lo <= hi) {
        int cut1 = (lo+hi)/2, cut2 = k-cut1;
        int l1 = cut1>0 ? arr1[cut1-1] : INT_MIN;
        int l2 = cut2>0 ? arr2[cut2-1] : INT_MIN;
        int r1 = cut1<n ? arr1[cut1] : INT_MAX;
        int r2 = cut2<m ? arr2[cut2] : INT_MAX;
        if (l1<=r2 && l2<=r1) return max(l1, l2);
        else if (l1 > r2) hi = cut1-1;
        else lo = cut1+1;
    }
    return -1;
}

