pair<int,int> jobScheduling(vector<tuple<int,int,int>>& jobs) {
    sort(jobs.begin(), jobs.end(), [](auto& a, auto& b) { return get<2>(a)>get<2>(b); });
    int maxD=0;
    for (auto& [id,d,p] : jobs) maxD=max(maxD,d);
    vector<int> parent(maxD+1);
    iota(parent.begin(), parent.end(), 0);
    function<int(int)> find = [&](int x) { return parent[x]==x ? x : parent[x]=find(parent[x]); };
    int profit=0, count=0;
    for (auto& [id,d,p] : jobs) {
        int slot=find(d);
        if (slot>0) { parent[slot]=find(slot-1); profit+=p; count++; }
    }
    return {count, profit};
}

