static int[] jobScheduling(int[][] jobs) {
    Arrays.sort(jobs, (a,b) -> b[2]-a[2]);
    int maxD=0;
    for (int[] j : jobs) maxD=Math.max(maxD,j[1]);
    int[] parent = new int[maxD+1];
    for (int i=0; i<=maxD; i++) parent[i]=i;
    int profit=0, count=0;
    for (int[] job : jobs) {
        int slot=find(parent,job[1]);
        if (slot>0) { parent[slot]=find(parent,slot-1); profit+=job[2]; count++; }
    }
    return new int[]{count, profit};
}
static int find(int[] parent, int x) {
    if (parent[x]!=x) parent[x]=find(parent,parent[x]);
    return parent[x];
}

