def double_helix(a, b):
    i = j = s1 = s2 = result = 0
    while i < len(a) and j < len(b):
        if a[i] < b[j]: s1 += a[i]; i += 1
        elif a[i] > b[j]: s2 += b[j]; j += 1
        else:
            result += max(s1, s2) + a[i]
            s1 = s2 = 0; i += 1; j += 1
    while i < len(a): s1 += a[i]; i += 1
    while j < len(b): s2 += b[j]; j += 1
    return result + max(s1, s2)

