int subsetSums(vector<int>& arr, int target) {
    auto gen = [](vector<int>& a) {
        vector<int> sums = {0};
        for (int x : a) {
            int sz = sums.size();
            for (int i=0; i<sz; i++) sums.push_back(sums[i]+x);
        }
        return sums;
    };
    int n=arr.size();
    vector<int> la(arr.begin(), arr.begin()+n/2);
    vector<int> ra(arr.begin()+n/2, arr.end());
    vector<int> left=gen(la), right=gen(ra);
    sort(right.begin(), right.end());
    int count=0;
    for (int s : left) {
        auto it=lower_bound(right.begin(),right.end(),target-s);
        if (it!=right.end() && s+*it==target) count++;
    }
    return count;
}

