static int subsetSums(int[] arr, int target) {
    int n=arr.length;
    List<Integer> left=genSums(Arrays.copyOfRange(arr,0,n/2));
    List<Integer> right=genSums(Arrays.copyOfRange(arr,n/2,n));
    Collections.sort(right);
    int count=0;
    for (int s : left) {
        int idx=Collections.binarySearch(right,target-s);
        if (idx>=0) count++;
    }
    return count;
}
static List<Integer> genSums(int[] a) {
    List<Integer> sums=new ArrayList<>();
    sums.add(0);
    for (int x : a) {
        int sz=sums.size();
        for (int i=0;i<sz;i++) sums.add(sums.get(i)+x);
    }
    return sums;
}

