    if (lo >= hi) return 0;
    int mid = (lo+hi)/2;
    long long inv = mergeSortCount(arr,tmp,lo,mid) + mergeSortCount(arr,tmp,mid+1,hi);
    int i=lo, j=mid+1, k=lo;
    while (i<=mid && j<=hi) {
        if (arr[i]<=arr[j]) tmp[k++]=arr[i++];
        else { tmp[k++]=arr[j++]; inv += mid-i+1; }
    }
    while (i<=mid) tmp[k++]=arr[i++];
    while (j<=hi) tmp[k++]=arr[j++];
    for (i=lo; i<=hi; i++) arr[i]=tmp[i];
    return inv;
}
long long inversionCount(vector<int>& arr) {
    vector<int> tmp(arr.size());
    return mergeSortCount(arr, tmp, 0, arr.size()-1);
}

