def three_way_partition(arr):
    lo, mid, hi = 0, 0, len(arr) - 1
    pivot = arr[len(arr) // 2]
    while mid <= hi:
        if arr[mid] < pivot:
            arr[lo], arr[mid] = arr[mid], arr[lo]
            lo += 1; mid += 1
        elif arr[mid] > pivot:
            arr[mid], arr[hi] = arr[hi], arr[mid]
            hi -= 1
        else:
            mid += 1
    return arr

