vector<int> threeWayPartition(vector<int>& arr) {
    int lo=0, mid=0, hi=arr.size()-1;
    int pivot=arr[arr.size()/2];
    while (mid<=hi) {
        if (arr[mid]<pivot) { swap(arr[lo],arr[mid]); lo++; mid++; }
        else if (arr[mid]>pivot) { swap(arr[mid],arr[hi]); hi--; }
        else mid++;
    }
    return arr;
}

