class MaxHeap {
    vector<int> h;
public:
    MaxHeap(vector<int>& a) : h(a) {
        for (int i = h.size()/2-1; i >= 0; i--) heapify(i);
    }
    void heapify(int i) {
        int largest = i, l = 2*i+1, r = 2*i+2, n = h.size();
        if (l < n && h[l] > h[largest]) largest = l;
        if (r < n && h[r] > h[largest]) largest = r;
        if (largest != i) { swap(h[i], h[largest]); heapify(largest); }
    }
    void insert(int val) {
        h.push_back(val);
        int i = h.size()-1;
        while (i > 0 && h[(i-1)/2] < h[i]) {
            swap(h[(i-1)/2], h[i]); i = (i-1)/2;
        }
    }
    int extractMax() {
        int root = h[0]; h[0] = h.back(); h.pop_back();
        heapify(0); return root;
    }
};

