def max_subarrays_size_k(arr, k):
    dq = deque()
    result = []
    for i in range(len(arr)):
        while dq and dq[0] <= i - k: dq.popleft()
        while dq and arr[dq[-1]] <= arr[i]: dq.pop()
        dq.append(i)
        if i >= k - 1: result.append(arr[dq[0]])
    return result

