vector<int> mergeMaxHeaps(vector<int>& a, vector<int>& b) {
    vector<int> m=a;
    m.insert(m.end(), b.begin(), b.end());
    int n=m.size();
    auto hp=[&](auto&& self, int n, int i)->void {
        int lg=i, l=2*i+1, r=2*i+2;
        if (l<n && m[l]>m[lg]) lg=l;
        if (r<n && m[r]>m[lg]) lg=r;
        if (lg!=i) { swap(m[i],m[lg]); self(self,n,lg); }
    };
    for (int i=n/2-1;i>=0;i--) hp(hp,n,i);
    return m;
}

