def kth_largest_sum(arr, k):
    n = len(arr)
    prefix = [0]*(n+1)
    for i in range(n): prefix[i+1] = prefix[i] + arr[i]
    pq = []
    for i in range(n):
        for j in range(i, n):
            s = prefix[j+1] - prefix[i]
            if len(pq) < k: heapq.heappush(pq, s)
            elif s > pq[0]: heapq.heapreplace(pq, s)
    return pq[0]

