import heapq
from collections import Counter
def reorganize_string(s):
    count = Counter(s)
    if max(count.values()) > (len(s)+1)//2: return ""
    heap = [(-f, c) for c, f in count.items()]
    heapq.heapify(heap)
    result = []
    while heap:
        f1, c1 = heapq.heappop(heap)
        result.append(c1)
        if heap:
            f2, c2 = heapq.heappop(heap)
            result.append(c2)
            if f2+1 < 0: heapq.heappush(heap, (f2+1, c2))
        if f1+1 < 0: heapq.heappush(heap, (f1+1, c1))
    return "".join(result)

