        auto [f1,c1]=pq.top(); pq.pop();
        auto [f2,c2]=pq.top(); pq.pop();
        r+=c1; r+=c2;
        if (f1>1) pq.push({f1-1,c1});
        if (f2>1) pq.push({f2-1,c2});
    }
    if (!pq.empty()) {
        if (pq.top().first>1) return "";
        r+=pq.top().second;
    }
    return r;
}

