static String reorganizeString(String s) {
    int[] cnt=new int[26];
    for (char c:s.toCharArray()) cnt[c-'a']++;
    PriorityQueue<int[]> pq = new PriorityQueue<>((a,b)->b[0]-a[0]);
    for (int i=0;i<26;i++) if (cnt[i]>0) pq.add(new int[]{cnt[i],i});
    if (pq.peek()[0]>(s.length()+1)/2) return "";
    StringBuilder r = new StringBuilder();
    while (pq.size()>1) {
        int[] a=pq.poll(), b=pq.poll();
        r.append((char)('a'+a[1]));
        r.append((char)('a'+b[1]));
        if (a[0]>1) pq.add(new int[]{a[0]-1,a[1]});
        if (b[0]>1) pq.add(new int[]{b[0]-1,b[1]});
    }
    if (!pq.isEmpty()) {
        if (pq.peek()[0]>1) return "";
        r.append((char)('a'+pq.peek()[1]));
    }
    return r.toString();
}

