    int mx=Integer.MIN_VALUE;
    for (int i=0;i<lists.length;i++) { pq.add(new int[]{lists[i][0],i,0}); mx=Math.max(mx,lists[i][0]); }
    int[] r={Integer.MIN_VALUE,Integer.MAX_VALUE};
    while (true) {
        int[] c=pq.poll();
        if (mx-c[0]<r[1]-r[0]) r=new int[]{c[0],mx};
        if (c[2]+1==lists[c[1]].length) break;
        int nv=lists[c[1]][c[2]+1];
        pq.add(new int[]{nv,c[1],c[2]+1}); mx=Math.max(mx,nv);
    }
    return r;
}

