bool isHeap(TreeNode* root) {
    if (!root) return true;
    queue<TreeNode*> q; q.push(root);
    bool end=false;
    while (!q.empty()) {
        TreeNode* n=q.front(); q.pop();
        if (n->left) {
            if (end||n->val<n->left->val) return false;
            q.push(n->left);
        } else end=true;
        if (n->right) {
            if (end||n->val<n->right->val) return false;
            q.push(n->right);
        } else end=true;
    }
    return true;
}

