void minToMaxHeap(vector<int>& arr) {
    int n=arr.size();
    auto hp=[&](auto&& self, int n, int i)->void {
        int lg=i,l=2*i+1,r=2*i+2;
        if (l<n&&arr[l]>arr[lg]) lg=l;
        if (r<n&&arr[r]>arr[lg]) lg=r;
        if (lg!=i) { swap(arr[i],arr[lg]); self(self,n,lg); }
    };
    for (int i=n/2-1;i>=0;i--) hp(hp,n,i);
}

