bool solveSudoku(vector<vector<char>>& b) {
    for (int i=0;i<9;i++) for (int j=0;j<9;j++) {
        if (b[i][j]!='.') continue;
        for (char c='1';c<='9';c++) {
            bool ok=true;
            for (int k=0;k<9;k++)
                if (b[i][k]==c||b[k][j]==c||b[3*(i/3)+k/3][3*(j/3)+k%3]==c) {ok=false;break;}
            if (ok) { b[i][j]=c;
                if (solveSudoku(b)) return true;
                b[i][j]='.';
            }
        }
        return false;
    }
    return true;
}

