def find_celebrity(n, knows):
    stack = list(range(n))
    while len(stack) > 1:
        a = stack.pop(); b = stack.pop()
        if knows(a, b): stack.append(b)
        else: stack.append(a)
    c = stack[0]
    for i in range(n):
        if i != c and (knows(c, i) or not knows(i, c)): return -1
    return c

