int findCelebrity(int n, auto knows) {
    stack<int> s;
    for (int i=0;i<n;i++) s.push(i);
    while (s.size()>1) {
        int a=s.top();s.pop(); int b=s.top();s.pop();
        if (knows(a,b)) s.push(b); else s.push(a);
    }
    int c=s.top();
    for (int i=0;i<n;i++) if (i!=c&&(knows(c,i)||!knows(i,c))) return -1;
    return c;
}

