class LRUCache {
    int cap;
    list<pair<int,int>> l;
    unordered_map<int,list<pair<int,int>>::iterator> m;
public:
    LRUCache(int c):cap(c){}
    int get(int key) {
        if (m.find(key)==m.end()) return -1;
        l.splice(l.begin(),l,m[key]);
        return m[key]->second;
    }
    void put(int key, int val) {
        if (m.find(key)!=m.end()) l.splice(l.begin(),l,m[key]);
        else if (l.size()==cap) { m.erase(l.back().first); l.pop_back(); }
        l.push_front({key,val}); m[key]=l.begin();
    }
};

