def next_smaller(nums):
    n = len(nums)
    result = [-1] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and stack[-1] >= nums[i]: stack.pop()
        if stack: result[i] = stack[-1]
        stack.append(nums[i])
    return result

