        self.children = {}
        self.is_end = False

def longest_common_prefix(strs):
    if not strs: return ""
    root = TrieNode()
    for s in strs:
        node = root
        for c in s:
            if c not in node.children: node.children[c] = TrieNode()
            node = node.children[c]
        node.is_end = True
    prefix = []
    node = root
    while len(node.children) == 1 and not node.is_end:
        c = next(iter(node.children))
        prefix.append(c)
        node = node.children[c]
    return "".join(prefix)

