        TrieNode* n=root;
        for (char c:s) { if (!n->ch.count(c)) n->ch[c]=new TrieNode(); n=n->ch[c]; }
        n->isEnd=true;
    }
    string p;
    TrieNode* n=root;
    while (n->ch.size()==1&&!n->isEnd) {
