    for (String s:strs) {
        TrieNode n=root;
        for (char c:s.toCharArray()) {
            if (n.ch[c-'a']==null) n.ch[c-'a']=new TrieNode();
            n=n.ch[c-'a'];
        }
        n.isEnd=true;
    }
    StringBuilder p=new StringBuilder();
    TrieNode n=root;
    int cnt=0; char only=0;
    for (int i=0;i<26;i++) if (n.ch[i]!=null){cnt++;only=(char)('a'+i);}
    while (cnt==1&&!n.isEnd) {
        p.append(only); n=n.ch[only-'a'];
        cnt=0;
        for (int i=0;i<26;i++) if (n.ch[i]!=null){cnt++;only=(char)('a'+i);}
    }
    return p.toString();
}

